#!/bin/zsh
source ~/.nvm/nvm.sh
nvm use 24 >/dev/null 2>&1
openclaw browser focus neuro1 >/dev/null 2>&1
openclaw browser evaluate --json --fn 'function(){ function getStat(a, testid){ const b = a.querySelector(`[data-testid="${testid}"]`); if(!b) return null; const txt = b.innerText.replace(/[^0-9.,KMB]/g,"").trim(); return txt || null; } const articles = Array.from(document.querySelectorAll("article")); return articles.slice(0, 30).map(a => { const getText = sel => { const el = a.querySelector(sel); return el ? el.innerText.trim().replace(/\\s+/g, " ") : ""; }; const authorEl = a.querySelector("[data-testid=User-Name]"); const author = authorEl ? (authorEl.querySelector("a span")?.innerText || "") : ""; const handle = authorEl ? (authorEl.querySelectorAll("a")[1]?.innerText || "") : ""; const timeEl = a.querySelector("time"); const date = timeEl ? timeEl.getAttribute("datetime") : ""; const text = getText("[data-testid=tweetText]"); const url = timeEl ? (timeEl.parentElement?.getAttribute("href") || "") : ""; return { author, handle, date, text, stats: { replies: getStat(a,"reply"), reposts: getStat(a,"retweet"), likes: getStat(a,"like"), bookmarks: getStat(a,"bookmark") }, url }; }); }'
